    @pydantic.field_validator("string_value")
    @classmethod
    def _validate_string_length(cls, v: str) -> str:
        """Validate that string_value is between 1 and 500 characters."""
        if not (1 <= len(v) <= 500):
            raise ValueError("string_value must be 1-500 characters long")
        return v"
