  "test": "import pytest
from pydantic import ValidationError
from langfuse.api.commons.types.text_score import TextScore


def test_text_score_valid_lengths():
    # Minimum length (1 character)
    TextScore(string_value="a")
    # Maximum length (500 characters)
    TextScore(string_value="x" * 500)


def test_text_score_invalid_lengths():
    # Empty string should raise ValidationError
    with pytest.raises(ValidationError):
        TextScore(string_value="")
    # Exceeding max length should raise ValidationError
    with pytest.raises(ValidationError):
        TextScore(string_value="x" * 501)
